class ATM {
    vector<long long> counts;
    vector<long long> denoms = {20, 50, 100, 200, 500};

public:
    ATM() : counts(5, 0) {}

    void deposit(vector<int> banknotesCount) {
        for (int i = 0; i < 5; i++) {
            counts[i] += banknotesCount[i];
        }
    }

    vector<int> withdraw(int amount) {
        vector<int> take(5, 0);
        long long rem = amount;
        for (int i = 4; i >= 0; i--) {
            long long cnt = min(counts[i], rem / denoms[i]);
            take[i] = cnt;
            rem -= cnt * denoms[i];
        }
        if (rem == 0) {
            for (int i = 0; i < 5; i++) {
                counts[i] -= take[i];
            }
            return take;
        }
        return {-1};
    }
};

class ATM {
    private long[] counts = new long[5];
    private int[] denoms = {20, 50, 100, 200, 500};

    public ATM() {}

    public void deposit(int[] banknotesCount) {
        for (int i = 0; i < 5; i++) {
            counts[i] += banknotesCount[i];
        }
    }

    public int[] withdraw(int amount) {
        int[] take = new int[5];
        long rem = amount;
        for (int i = 4; i >= 0; i--) {
            long cnt = Math.min(counts[i], rem / denoms[i]);
            take[i] = (int) cnt;
            rem -= cnt * denoms[i];
        }
        if (rem == 0) {
            for (int i = 0; i < 5; i++) {
                counts[i] -= take[i];
            }
            return take;
        }
        return new int[]{-1};
    }
}

var ATM = function() {
    this.denoms = [20, 50, 100, 200, 500];
    this.counts = [0, 0, 0, 0, 0];
};

/** 
 * @param {number[]} banknotesCount
 * @return {void}
 */
ATM.prototype.deposit = function(banknotesCount) {
    for (let i = 0; i < 5; i++) {
        this.counts[i] += banknotesCount[i];
    }
};

/** 
 * @param {number} amount
 * @return {number[]}
 */
ATM.prototype.withdraw = function(amount) {
    const take = [0, 0, 0, 0, 0];
    let rem = amount;
    for (let i = 4; i >= 0; i--) {
        const cnt = Math.min(this.counts[i], Math.floor(rem / this.denoms[i]));
        take[i] = cnt;
        rem -= cnt * this.denoms[i];
    }
    if (rem === 0) {
        for (let i = 0; i < 5; i++) {
            this.counts[i] -= take[i];
        }
        return take;
    }
    return [-1];
};
